delete t from t_quartz_task_status t
WHERE t.plan_id = #{taskId}
and t.data_date = #{dataDate}

UPDATE t_quartz_task_status t
set t.status = #{taskStatusEntity.status}
,t.msg = #{taskStatusEntity.msg}
,update_time = #{taskStatusEntity.updateTime}
  ,end_time = #{taskStatusEntity.endTime}

    , begin_time =  #{taskStatusEntity.beginTime}

WHERE t.plan_id  = #{taskStatusEntity.planId}
and t.data_date = #{taskStatusEntity.dataDate}

mapper.select:
SELECT s.plan_id, s.id, t.task_name, t.task_cron, t.remark, t.task_type, t.exe_path, ( SELECT GROUP_CONCAT(d.pre_task_id ORDER BY d.pre_task_id SEPARATOR ',') FROM t_quartz_task_dependency d WHERE d.task_id = t.id AND d.dependency_type = 'DATA' ) AS depend_id, ( SELECT GROUP_CONCAT(d.pre_task_id ORDER BY d.pre_task_id SEPARATOR ',') FROM t_quartz_task_dependency d WHERE d.task_id = t.id AND d.dependency_type = 'DATA' ) AS data_depend_id, ( SELECT GROUP_CONCAT(d.pre_task_id ORDER BY d.pre_task_id SEPARATOR ',') FROM t_quartz_task_dependency d WHERE d.task_id = t.id AND d.dependency_type = 'CONTROL' ) AS control_depend_id, t.datasource_id, ds.name AS datasource_name, t.datasource_pool_id, dsp.name AS datasource_pool_name, t.task_system, t.theme, t.period, s.data_date, s.STATUS, s.begin_time, s.update_time, s.end_time, s.msg, s.execute_pool_id, s.execute_pool_name, s.execute_datasource_id, s.execute_datasource_name, case when s.status = '3' or s.status = '4' then 'true' else 'false' end as _disabled, s.create_time FROM t_quartz_task_status s INNER JOIN t_quartz_task t ON s.plan_id = t.id LEFT JOIN sys_datasource_config ds ON ds.id = t.datasource_id LEFT JOIN sys_datasource_pool dsp ON dsp.id = t.datasource_pool_id WHERE 1=1
and s.create_date = #{queryDTO.beginDate}
and s.data_date = #{queryDTO.dataDate}
AND t.id = #{queryDTO.id}
AND INSTR(t.task_name,#{queryDTO.taskName})
AND INSTR(t.task_system,#{queryDTO.taskSystem})
AND INSTR(t.theme,#{queryDTO.theme})
AND s.STATUS = #{queryDTO.status}
order by s.update_time desc

SELECT status FROM t_quartz_task_status
WHERE plan_id = #{planId} AND data_date = #{dataDate}
LIMIT 1

SELECT id, plan_id as planId, data_date as dataDate, status, begin_time as beginTime, end_time as endTime, msg, create_time as createTime, update_time as updateTime FROM t_quartz_task_status WHERE plan_id IN
#{id}
AND data_date BETWEEN #{startDate} AND #{endDate}
